# Define Z3 elements: 0, 1, 2
Z3 = [0, 1, 2]

# Iterate over all pairs (a3, a1) in Z3 x Z3
count = 0
for a3 in Z3:
    for a1 in Z3:
        # Condition 1: Must not be (0, 0)
        if a3 == 0 and a1 == 0:
            continue

        # Condition 2: a3 + a1 must not be congruent to 0 mod 3
        if (a3 + a1) % 3 != 0:
            count += 1

print(count)
